def mask_name(s):
    return s[0] + "*" * (len(s) - 2) + s[-1] if len(s) > 2 else s[0] + "*"

def mask_phone(s):
    a, _, c = s.split("-")
    return f"{a}-****-{c}"

def mask_acct(s):
    return "*" * (len(s) - 4) + s[-4:]

print(mask_name("홍길동"), mask_name("김수"), mask_phone("010-1234-5678"), mask_acct("12345678901"))
